) ?? (() => { throw new Error("unresolved:" + "detailData.bzProcsNo"); })()))).length === 0) && $c.session.getUserInfo("repIdYn") !=='Y'); } }, { id: "btn_goEditForm_3", fn: function(){ return ((dma_detailData.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "detailData.bzProcsNo"); })()) ===''||(String(((dma_detailData.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "detailData.bzProcsNo"); })())) == null ? '' : ((dma_detailData.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "detailData.bzProcsNo"); })()))).length === 0) && $c.session.getUserInfo("repIdYn") !=='Y'); } }, { id: "btn_doDelete", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_doSave", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_goEditForm", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_doDelete_2", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_doSave_2", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_goEditForm_2", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_doDelete_3", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_doSave_3", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }, { id: "btn_goEditForm_3", fn: function(){ return ((dma_pageContext.get("closeYn") ?? "")!== 'N'); } }];
