scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.attachFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles"]');
        scwin.attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_2"]');
        scwin.attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_3"]');
        scwin.attachFiles_2_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_2_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_2_2"]');
        scwin.bzRegNo = '' + dma_detailData.get("bz_reg_no") + '';
        scwin.checkIsurCd = scwin.tx_checkIsurCd;
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71302.onpageload' });
    }
};

