 */
scwin.setFileDisable = function () {
    const obj1 = $c.util.getComponent('attachFiles');
    const obj2 = $c.util.getComponent('attachFiles_3');
    obj1.setDisabled(true);
    obj2.setDisabled(true);
};

/**
 * @method
 * @name setData
 * @description set Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setData = function () {
    if (scwin.bzRegNo.length = 10) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(scwin.bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(scwin.bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(scwin.bzRegNo.substring(5, 10));
    }
};

