};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} stdCd stdCd
 * @param {*} isuAbbrv isuAbbrv
 * @param {String} ipt_isuNm ipt_isuNm
 * @param {String} isurCd isurCd
 * @param {String} ipt_comNm ipt_comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} bzRegNo bzRegNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (stdCd, isuAbbrv, ipt_isuNm, isurCd, ipt_comNm, comAbbrv, bzRegNo) {
    if ('' !== stdCd) {
        $c.util.getComponent("ipt_isuCd").setValue(stdCd);
    } else {
        await $c.win.alert('선택하신 종목명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if ('' !== isuAbbrv) {
        $c.util.getComponent("ipt_isuNm").setValue(isuAbbrv);
    } else {
        await $c.win.alert('선택하신 종목명의 종목명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if (('' !== isurCd) && (isurCd.length === 5)) {
