                if (await $c.win.confirm('작성된 내용을 수정하시겠습니까?')) {
                    (($c.util.getComponent('slc_designAdvserIsurCd')) && ($c.util.getComponent('slc_designAdvserIsurCd')).setDisabled ? ($c.util.getComponent('slc_designAdvserIsurCd')).setDisabled((('') === '' || ('') === false || ('') === 'false') ? false : ((('') === true || ('') === 'true' || ('') === 'disabled') ? true : (''))) : void 0);
                    await scwin.tx_doSave();
                }
            } else {
                if (form.method.value === 'write') {
                    if (await $c.win.confirm('작성된 내용을 저장하시겠습니까?')) {
                        (($c.util.getComponent('slc_designAdvserIsurCd')) && ($c.util.getComponent('slc_designAdvserIsurCd')).setDisabled ? ($c.util.getComponent('slc_designAdvserIsurCd')).setDisabled((('') === '' || ('') === false || ('') === 'false') ? false : ((('') === true || ('') === 'true' || ('') === 'disabled') ? true : (''))) : void 0);
                        await scwin.tx_doSave();
                    }
                }
            }
        }
    }
};

